from contextlib import closing

from ledger_db import decode_balance, encode_balance, open_ledger


def post(opening, transfers):
    statuses = []
    with closing(open_ledger(opening)) as conn, conn:
        for transfer_id, source, target, amount in transfers:
            if conn.execute(
                "SELECT 1 FROM posted_transfers WHERE id IS ?", (transfer_id,)
            ).fetchone() is not None:
                statuses.append("duplicate")
                continue

            accounts = dict(conn.execute(
                "SELECT name, balance FROM accounts WHERE name IN (?, ?)",
                (source, target),
            ))
            if source not in accounts or target not in accounts:
                statuses.append("unknown")
                continue

            source_balance = decode_balance(accounts[source])
            if source_balance < amount:
                statuses.append("insufficient")
                continue

            if source != target:
                target_balance = decode_balance(accounts[target])
                conn.executemany(
                    "UPDATE accounts SET balance = ? WHERE name = ?",
                    ((encode_balance(source_balance - amount), source),
                     (encode_balance(target_balance + amount), target)),
                )
            conn.execute("INSERT INTO posted_transfers VALUES (?)", (transfer_id,))
            statuses.append("posted")

        return {
            "balances": {
                name: decode_balance(balance)
                for name, balance in conn.execute("SELECT name, balance FROM accounts")
            },
            "statuses": statuses,
        }
